                if increase > max_increase:
                    max_increase = increase
                    best_operation = ('multiply', i)

        if best_operation is None:
            break

        op, i = best_operation
        if op == 'divide':
            a[i] //= 2
        else:
            a[i] *= 3

        operations += 1

    return operations

