def max_operations(N, a):
    def count_divisible_by_2(x):
        count = 0
        while x % 2 == 0:
            x //= 2
            count += 1
        return count

    total_operations = 0
    for _ in range(N):
        max_divides = 0
        best_index = -1
        for i in range(N):
            if a[i] % 2 == 0:
                divides = count_divisible_by_2(a[i])
                if divides > max_divides:
                    max_divides = divides
                    best_index = i
        if best_index == -1:
            break
        total_operations += max_divides
        a[best_index] //= (2 ** max_divides)

    return total_operations

